/*
 * Pro tips
 * - Equal sets are insufficient: aab and abb have different frequencies.
 * - Reject unequal lengths, then count s and consume counts with t.
 * - Reject a missing character or a count below zero. Equal lengths ensure all counts are exhausted on success.
 * - Check repeated letters, unequal lengths, and identical strings; comparison is case-sensitive.
 * - Complexity: O(n + m) expected time, O(u) space.
 */

import java.util.HashMap;
import java.util.Scanner;

class Solution {
    public static boolean validAnagram(String s, String t) {
        if (s.length() != t.length()) {
            return false;
        }

        HashMap<Character, Integer> charCount = new HashMap<>();

        // Count characters in s
        for (char c : s.toCharArray()) {
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }

        // Decrease count for characters in t
        for (char c : t.toCharArray()) {
            if (!charCount.containsKey(c)) {
                return false;
            }
            charCount.put(c, charCount.get(c) - 1);
            if (charCount.get(c) < 0) {
                return false;
            }
        }

        return true;
    }

    public static void main(String[] args) {
        java.util.Scanner scanner = new java.util.Scanner(System.in);
        String s = scanner.nextLine();
        String t = scanner.nextLine();
        scanner.close();
        boolean res = validAnagram(s, t);
        System.out.println(res);
    }
}
